import { useEffect, useEffectEvent, useRef } from "react"

import type { DiffViewController } from "@/components/ui/diff-view-primitive"

/**
 * Scrolls the diff to `currentFile` when the caller changes it, and not when it only echoes the file the diff
 * reported while scrolling: call the returned function with each file the diff reports.
 */
function useOpenCurrentFile(
  controller: DiffViewController,
  currentFile: string | null | undefined,
  known: (path: string) => boolean,
) {
  const shown = useRef<string | null>(null)
  const isKnown = useEffectEvent(known)
  useEffect(() => {
    if (currentFile == null || currentFile === shown.current || !isKnown(currentFile)) return
    shown.current = currentFile
    controller.openFile(currentFile)
  }, [controller, currentFile])
  return (path: string | null) => {
    shown.current = path
  }
}

export { useOpenCurrentFile }

"use client"

import {
  Tree,
  TreeGroup,
  TreeItem,
  TreeItemIndicator,
  TreeItemLabel,
  treeFromPaths,
  type TreeItemData,
} from "@ui-sdk/react/tree"
import { ChevronRightIcon, FileDiffIcon, FileMinusIcon, FilePlusIcon, FileSymlinkIcon, FolderIcon } from "lucide-react"
import { useMemo } from "react"

import type { DiffLabels } from "@/components/ui/diff-labels"
import { FileChange } from "@/components/ui/diff-stat"
import type { DiffViewFile } from "@/components/ui/diff-view-model"
import { ScrollArea, ScrollAreaScrollbar, ScrollAreaViewport } from "@/components/ui/scroll-area"
import type { FileStatus } from "@/lib/diff-types"
import { cn } from "@/lib/utils"

const statusIcon: Record<FileStatus, typeof FileDiffIcon> = {
  added: FilePlusIcon,
  deleted: FileMinusIcon,
  modified: FileDiffIcon,
  renamed: FileSymlinkIcon,
  copied: FileSymlinkIcon,
}

const statusColour: Record<FileStatus, string> = {
  added: "text-diff-added-foreground",
  deleted: "text-diff-removed-foreground",
  modified: "text-muted-foreground",
  renamed: "text-muted-foreground",
  copied: "text-muted-foreground",
}

type Section = TreeItemData & { count?: number }

function Items({
  items,
  files,
  labels,
}: {
  items: Section[]
  files: ReadonlyMap<string, DiffViewFile>
  labels: DiffLabels
}) {
  return items.map((item) => {
    if (item.count !== undefined) {
      return (
        <TreeItem key={item.value} value={item.value} className="outline-none">
          <TreeItemLabel
            data-group=""
            className="flex cursor-pointer items-center gap-inline rounded-control px-inline py-inset-item text-body-sm font-medium hover:bg-accent hover:text-accent-foreground [:focus-visible>&]:outline-2 [:focus-visible>&]:outline-ring"
          >
            <TreeItemIndicator className="inline-flex data-expanded:rotate-90 rtl:rotate-180 rtl:data-expanded:rotate-90">
              <ChevronRightIcon aria-hidden="true" className="size-3.5" />
            </TreeItemIndicator>
            <span className="min-w-0 flex-1 truncate">{item.label}</span>
            <span className="text-caption font-normal text-muted-foreground tabular-nums">
              {labels.fileCount(item.count)}
            </span>
          </TreeItemLabel>
          <TreeGroup>
            <Items items={item.children ?? []} files={files} labels={labels} />
          </TreeGroup>
        </TreeItem>
      )
    }
    const file = files.get(item.value)
    const Icon = file ? statusIcon[file.diff.status] : FolderIcon
    return (
      <TreeItem key={item.value} value={item.value} className="outline-none">
        <TreeItemLabel
          className={cn(
            // oxlint-disable-next-line shadcn/no-arbitrary-values -- indents each level by a group gap, from the tree's --tree-level
            "flex cursor-pointer items-center gap-inline rounded-control py-inset-item pe-inline ps-[calc(var(--tree-level)*var(--gap-group)-var(--gap-inline))] text-body-sm",
            "hover:bg-accent hover:text-accent-foreground [:focus-visible>&]:outline-2 [:focus-visible>&]:outline-ring data-selected:bg-accent data-selected:text-accent-foreground",
          )}
        >
          {item.children ? (
            <TreeItemIndicator className="inline-flex data-expanded:rotate-90 rtl:rotate-180 rtl:data-expanded:rotate-90">
              <ChevronRightIcon aria-hidden="true" className="size-3.5" />
            </TreeItemIndicator>
          ) : null}
          <span className={cn("inline-flex shrink-0", file ? statusColour[file.diff.status] : "text-muted-foreground")}>
            <Icon aria-hidden="true" className="size-3.5" />
          </span>
          <span className="min-w-0 flex-1 truncate">{item.label}</span>
          {file ? (
            <>
              <span className="sr-only">{labels.status[file.diff.status]}</span>
              <FileChange diff={file.diff} labels={labels} bar={false} />
            </>
          ) : null}
        </TreeItemLabel>
        {item.children ? (
          <TreeGroup>
            <Items items={item.children} files={files} labels={labels} />
          </TreeGroup>
        ) : null}
      </TreeItem>
    )
  })
}

/** Folder values carry their section, so a folder in two sections (src/ staged and unstaged) stays two items. */
function scoped(
  items: readonly TreeItemData[],
  scope: string,
  files: ReadonlyMap<string, DiffViewFile>,
): TreeItemData[] {
  return items.map((item) => {
    if (item.children) {
      return { ...item, value: `${scope}${item.value}`, children: scoped(item.children, scope, files) }
    }
    // A path in two groups is `path (2)` in the second; its section already tells them apart.
    const diff = files.get(item.value)?.diff
    const real = diff?.newPath ?? diff?.oldPath
    return real ? { ...item, label: real.slice(real.lastIndexOf("/") + 1) } : item
  })
}

/** The tree's items: the files as folders, or one section per group with its own folders. */
function itemsOf(files: readonly DiffViewFile[], groups: readonly GitDiffTreeGroup[] | undefined): Section[] {
  if (!groups) return treeFromPaths(files.map((file) => file.path))
  const byPath = new Map(files.map((file) => [file.path, file]))
  return groups.map((group, index) => ({
    value: `\u0000group:${String(index)}`,
    label: group.label,
    count: group.paths.length,
    children: scoped(treeFromPaths(group.paths), `\u0000${String(index)}:`, byPath),
  }))
}

function folders(items: readonly TreeItemData[], out: string[] = []) {
  for (const item of items) {
    if (item.children) {
      out.push(item.value)
      folders(item.children, out)
    }
  }
  return out
}

/** A section of the tree, like "Staged", and the view paths of its files. */
type GitDiffTreeGroup = { label: string; paths: readonly string[] }

type GitDiffTreeProps = {
  files: readonly DiffViewFile[]
  /** Sections, each with its own folders; without them, one tree of every file. */
  groups?: readonly GitDiffTreeGroup[]
  /** The file shown, highlighted in the tree. */
  value?: string | null
  onOpen: (path: string) => void
  labels: DiffLabels
  className?: string
}

/** The changed files as a folder tree (UI SDK Tree): status icon, path and counts; choosing one opens it. */
function GitDiffTree({ files, groups, value, onOpen, labels, className }: GitDiffTreeProps) {
  const byPath = useMemo(() => new Map(files.map((file) => [file.path, file])), [files])
  const items = useMemo(() => itemsOf(files, groups), [files, groups])
  const open = useMemo(() => folders(items), [items])
  return (
    <ScrollArea className={cn("flex flex-col", className)}>
      <ScrollAreaViewport className="h-auto min-h-0 flex-1">
        <Tree
          aria-label={labels.files}
          items={items}
          defaultExpanded={open}
          value={value ?? null}
          onValueChange={(next) => {
            if (typeof next === "string" && byPath.has(next)) onOpen(next)
          }}
          className="flex flex-col"
        >
          <Items items={items} files={byPath} labels={labels} />
        </Tree>
      </ScrollAreaViewport>
      <ScrollAreaScrollbar data-agent-hidden="" />
      <ScrollAreaScrollbar orientation="horizontal" data-agent-hidden="" />
    </ScrollArea>
  )
}

export { GitDiffTree }
export type { GitDiffTreeGroup, GitDiffTreeProps }

"use client"

import { Columns2Icon, PanelLeftIcon, RowsIcon, WrapTextIcon } from "lucide-react"
import { useCallback, useMemo, useState } from "react"

import { diffLabels } from "@/components/ui/diff-labels"
import { DiffStat } from "@/components/ui/diff-stat"
import { DiffView, type DiffViewProps } from "@/components/ui/diff-view"
import { toViewFiles, type DiffLayout } from "@/components/ui/diff-view-model"
import { createDiffViewController, type DiffViewController } from "@/components/ui/diff-view-primitive"
import { GitDiffTree } from "@/components/ui/git-diff-tree"
import { SegmentedControl, SegmentedControlIndicator, SegmentedControlItem } from "@/components/ui/segmented-control"
import { Toggle } from "@/components/ui/toggle"
import { parsePatch } from "@/lib/diff-patch"
import type { FileDiff } from "@/lib/diff-types"
import { useOpenCurrentFile } from "@/components/ui/use-git-diff"
import { cn } from "@/lib/utils"

type GitDiffProps = Omit<DiffViewProps, "files" | "headers"> & {
  /** A unified diff as git prints it (`git diff`, `git show`, a `.patch`), with any number of files. */
  patch?: string
  /** File diffs you parsed or computed; give `oldText`/`newText` to make unchanged regions expandable. */
  files?: readonly FileDiff[]
  /**
   * The changed-files tree beside the diff, `--diff-tree-width` wide (13rem). `"collapsible"` adds a toggle
   * at the start of the toolbar to hide and show it. @defaultValue true
   */
  fileTree?: boolean | "collapsible"
  /** Whether a collapsible tree shows. */
  fileTreeOpen?: boolean
  defaultFileTreeOpen?: boolean
  onFileTreeOpenChange?: (open: boolean) => void
  /**
   * The files in sections, like the working tree's "Staged" and "Unstaged": each a `label` and its `files` or
   * `patch`, in order. The tree shows one section per group; the diff lists the groups one after another.
   */
  groups?: readonly GitDiffGroup[]
  /** The layout and wrap controls and the totals above the diff. @defaultValue true */
  toolbar?: boolean
  /**
   * `fill` (default) fills the height GitDiff is given, beside its file tree. `auto` grows to the diff up to
   * `--diff-max-height` (40rem), the tree beside it capped the same, for a diff inside a scrolling dialog body:
   * a short diff never scrolls on its own, and a long one hands the wheel back to the body at its ends.
   */
  height?: DiffViewProps["height"]
  /**
   * The file in view, for a file list or tree outside GitDiff: setting it scrolls the diff to that file, and
   * `onCurrentFileChange` reports the file at the top as the diff scrolls. The built-in tree follows it too.
   */
  currentFile?: string | null
  defaultCurrentFile?: string | null
}

/** A section of a GitDiff: its title in the file tree, and its files. */
type GitDiffGroup = { label: string; files?: readonly FileDiff[]; patch?: string }

const noGroups: readonly GitDiffGroup[] = []

// oxlint-disable-next-line shadcn/no-arbitrary-values -- a variable a page sets, with its default
const treeWidth = "w-[var(--diff-tree-width,13rem)]"
// oxlint-disable-next-line shadcn/no-arbitrary-values -- the same cap as the diff's, so the tree never outgrows it
const diffCap = "max-h-[var(--diff-max-height,40rem)]"

function useControlled<T>(value: T | undefined, initial: T, onChange?: (next: T) => void) {
  const [own, setOwn] = useState(initial)
  const current = value ?? own
  const set = (next: T) => {
    if (value === undefined) setOwn(next)
    onChange?.(next)
  }
  return [current, set] as const
}

/**
 * A patch or a list of file diffs, rendered for review: a header per file (rename, status, counts, collapse,
 * viewed), a tree of changed files to jump between them, unified or split layout and word wrap, all files and
 * lines in one virtualized scroller, j/k between hunks and n/p between files, line selection for comments, and
 * agent actions (openFile, nextHunk, previousHunk, markViewed, getHunk).
 */
function GitDiff({
  patch,
  files: given,
  groups,
  fileTree = true,
  fileTreeOpen,
  defaultFileTreeOpen = true,
  onFileTreeOpenChange,
  toolbar = true,
  labels = diffLabels,
  layout: layoutProp,
  defaultLayout = "unified",
  onLayoutChange,
  wrap: wrapProp,
  defaultWrap = false,
  onWrapChange,
  controller: controllerProp,
  height = "fill",
  currentFile: currentFileProp,
  defaultCurrentFile,
  onCurrentFileChange,
  className,
  ...props
}: GitDiffProps) {
  const sections = useMemo(
    () => (groups ?? noGroups).map((group) => group.files ?? (group.patch ? parsePatch(group.patch) : [])),
    [groups],
  )
  const diffs = useMemo(
    () => (groups ? sections.flat() : (given ?? (patch ? parsePatch(patch) : []))),
    [groups, sections, given, patch],
  )
  const files = useMemo(() => {
    const view = toViewFiles(diffs)
    if (!groups) return view
    const labelOf = sections.flatMap((list, index) => list.map(() => groups[index]?.label))
    return view.map((file, index) => ({ ...file, group: labelOf[index] }))
  }, [diffs, groups, sections])
  const treeGroups = useMemo(() => {
    if (!groups) return undefined
    const starts = sections.map((_, index) => sections.slice(0, index).reduce((sum, list) => sum + list.length, 0))
    return groups.map((group, index) => ({
      label: group.label,
      paths: files.slice(starts[index], (starts[index] ?? 0) + (sections[index]?.length ?? 0)).map((file) => file.path),
    }))
  }, [groups, sections, files])
  const [treeOpen, setTreeOpen] = useControlled(fileTreeOpen, defaultFileTreeOpen, onFileTreeOpenChange)
  const collapsible = fileTree === "collapsible" && toolbar
  const showTree = fileTree !== false && (files.length > 1 || groups !== undefined) && (!collapsible || treeOpen)
  const [own] = useState(createDiffViewController)
  const controller = controllerProp ?? own
  const [layout, setLayout] = useControlled<DiffLayout>(layoutProp, defaultLayout)
  const [wrap, setWrap] = useControlled(wrapProp, defaultWrap)
  const [ownCurrent, setOwnCurrent] = useState<string | null>(defaultCurrentFile ?? null)
  const current = currentFileProp === undefined ? ownCurrent : currentFileProp
  const known = useCallback((path: string) => files.some((file) => file.path === path), [files])
  const reported = useOpenCurrentFile(controller, current, known)
  const totals = useMemo(
    () =>
      diffs.reduce(
        (sum, file) => ({ additions: sum.additions + file.additions, deletions: sum.deletions + file.deletions }),
        { additions: 0, deletions: 0 },
      ),
    [diffs],
  )
  return (
    <div
      data-slot="git-diff"
      data-height={height}
      className={cn("flex flex-col gap-items", height === "auto" ? "shrink-0" : "min-h-0", className)}
    >
      {toolbar ? (
        <div data-slot="git-diff-toolbar" className="flex flex-wrap items-center gap-items">
          {collapsible ? (
            <Toggle
              variant="outline"
              size="icon"
              aria-label={labels.files}
              pressed={treeOpen}
              onPressedChange={setTreeOpen}
              className="narrow:hidden"
            >
              <PanelLeftIcon aria-hidden="true" />
            </Toggle>
          ) : null}
          <DiffStat additions={totals.additions} deletions={totals.deletions} labels={labels} />
          <div className="ms-auto flex items-center gap-items">
            <SegmentedControl<DiffLayout>
              aria-label={labels.layout}
              value={layout}
              onValueChange={(next) => {
                if (next) controller.setLayout(next)
              }}
            >
              <SegmentedControlIndicator />
              <SegmentedControlItem value="unified">
                <RowsIcon aria-hidden="true" />
                {labels.unified}
              </SegmentedControlItem>
              <SegmentedControlItem value="split">
                <Columns2Icon aria-hidden="true" />
                {labels.split}
              </SegmentedControlItem>
            </SegmentedControl>
            <Toggle variant="outline" pressed={wrap} onPressedChange={(next) => controller.setWrap(next)}>
              <WrapTextIcon aria-hidden="true" />
              {labels.wrap}
            </Toggle>
          </div>
        </div>
      ) : null}
      <div className="flex min-h-0 flex-1 gap-group">
        {showTree ? (
          <GitDiffTree
            files={files}
            groups={treeGroups}
            value={current}
            labels={labels}
            onOpen={(path) => controller.openFile(path)}
            className={cn(treeWidth, "shrink-0 narrow:hidden", height === "auto" && cn("self-start", diffCap))}
          />
        ) : null}
        <DiffView
          {...props}
          height={height}
          headers
          files={files}
          labels={labels}
          controller={controller}
          onCurrentFileChange={(path, details) => {
            reported(path)
            setOwnCurrent(path)
            onCurrentFileChange?.(path, details)
          }}
          layout={layout}
          onLayoutChange={(next, details) => {
            onLayoutChange?.(next, details)
            if (!details.canceled) setLayout(next)
          }}
          wrap={wrap}
          onWrapChange={(next, details) => {
            onWrapChange?.(next, details)
            if (!details.canceled) setWrap(next)
          }}
          className="min-w-0 flex-1"
        />
      </div>
    </div>
  )
}

export { createDiffViewController, GitDiff }
export type { DiffViewController, GitDiffGroup, GitDiffProps }
